import React, { useCallback, useEffect, useRef } from "react";
import useVoiceEngine from "./useVoiceEngine";
import EmailFormModal from "./EmailFormModal";
import TypewriterText from "./TypewriterText";
import { MicrophoneIcon } from "./SiriIcons";
import {
  Bubble,
  BubbleBar,
  BubbleScroll,
  Chip,
  ChipRow,
  IconButton,
  Line,
  ThinkingDots,
  TypeForm,
  TypeInput,
} from "./Pet.styles";

// Portfolio-tailored quick conversation starters
const OPENERS = [
  "Give me a quick overview",
  "What is his tech stack?",
  "Show me his best projects",
  "I want to hire Laxman",
];

const CloseGlyph = () => (
  <svg
    width="13"
    height="13"
    viewBox="0 0 24 24"
    fill="none"
    aria-hidden="true"
  >
    <path
      d="M6 6l12 12M18 6L6 18"
      stroke="currentColor"
      strokeWidth="2.4"
      strokeLinecap="round"
    />
  </svg>
);

const KeyboardGlyph = () => (
  <svg
    width="15"
    height="15"
    viewBox="0 0 24 24"
    fill="none"
    aria-hidden="true"
  >
    <rect
      x="2"
      y="6"
      width="20"
      height="12"
      rx="2.5"
      stroke="currentColor"
      strokeWidth="2"
    />
    <path
      d="M7 10h.01M11 10h.01M15 10h.01M8 14h8"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
    />
  </svg>
);

const PetBrain = ({
  name,
  theme,
  isMobile,
  signalRef,
  onDismiss,
  onDisable,
}) => {
  const {
    assistantState,
    clearTranscript,
    closeChat,
    connectionStatus,
    emailInquiryType,
    followUps,
    handleEmailFormSubmit,
    hasPermission,
    interimTranscript,
    isFirstInteraction,
    motionReduce,
    notice,
    requestMicrophonePermission,
    scrollTranscriptToEnd,
    setShowEmailForm,
    setShowTextInput,
    setTextInput,
    showEmailForm,
    showTextInput,
    speakIntroduction,
    startListening,
    stopAll,
    submitText,
    textInput,
    textInputRef,
    transcriptEntries,
    transcriptRef,
    voiceIntensity,
    panelRef,
  } = useVoiceEngine({ onClose: onDismiss });

  const isLight = theme?.name === "light";
  const isDisabled = connectionStatus !== "connected" || !hasPermission;

  // Hand live voice state to Pet.js animation loop without re-rendering bubble
  useEffect(() => {
    signalRef.current = {
      state: assistantState,
      intensity: voiceIntensity || 0,
    };
  }, [assistantState, voiceIntensity, signalRef]);

  useEffect(
    () => () => {
      signalRef.current = { state: "idle", intensity: 0 };
    },
    [signalRef]
  );

  // Auto-start listening on first interaction if mic permission exists
  const startedRef = useRef(false);
  useEffect(() => {
    if (startedRef.current || isDisabled) return;
    startedRef.current = true;
    if (isFirstInteraction) speakIntroduction();
    else startListening();
  }, [isDisabled, isFirstInteraction, speakIntroduction, startListening]);

  // Keyboard shortcut: Escape to close chat
  useEffect(() => {
    const onKeyDown = (e) => {
      if (e.key === "Escape") {
        e.preventDefault();
        closeChat();
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [closeChat]);

  // Focus input when text input opens
  useEffect(() => {
    if (showTextInput && textInputRef?.current) {
      setTimeout(() => textInputRef.current?.focus(), 60);
    }
  }, [showTextInput, textInputRef]);

  const onMicButton = useCallback(async () => {
    if (isDisabled) {
      if (connectionStatus === "connected") await requestMicrophonePermission();
      return;
    }
    if (assistantState === "idle") startListening();
    else stopAll();
  }, [
    assistantState,
    connectionStatus,
    isDisabled,
    requestMicrophonePermission,
    startListening,
    stopAll,
  ]);

  const shown = transcriptEntries.slice(-6);
  const greeting =
    shown.length === 0 && !interimTranscript && assistantState === "idle";

  return (
    <>
      <EmailFormModal
        show={showEmailForm}
        onClose={() => setShowEmailForm(false)}
        inquiryType={emailInquiryType}
        onSubmit={handleEmailFormSubmit}
        isMobile={isMobile}
        themeMode={isLight ? "light" : "dark"}
      />

      <Bubble ref={panelRef} theme={theme} isMobile={isMobile} wide>
        <BubbleScroll
          ref={transcriptRef}
          theme={theme}
          role="log"
          aria-live="polite"
          aria-label={`Conversation with ${name}`}
        >
          {notice && (
            <Line theme={theme} who="ai">
              <span className="who">{name}</span>
              <span className="said">
                <strong>{notice.title}</strong>
                {notice.content ? ` — ${notice.content}` : ""}
              </span>
            </Line>
          )}

          {greeting && !notice && (
            <Line theme={theme} who="ai">
              <span className="who">{name}</span>
              <span className="said">
                {isDisabled
                  ? "Tap the mic to talk, or drag me anywhere while you browse!"
                  : "Meow! drag & toss me around the page! 🐾"}
              </span>
            </Line>
          )}

          {shown.map((entry, i) => (
            <Line
              key={entry.id || `msg-${i}`}
              theme={theme}
              who={entry.role === "you" ? "you" : "ai"}
            >
              <span className="who">{entry.role === "you" ? "You" : name}</span>
              <span className="said">
                {entry.role === "ai" &&
                !entry.restored &&
                !entry.streamed &&
                i === shown.length - 1 ? (
                  <TypewriterText
                    text={entry.text}
                    instant={motionReduce}
                    onTick={scrollTranscriptToEnd}
                  />
                ) : (
                  entry.text
                )}
              </span>
            </Line>
          ))}

          {!!interimTranscript && (
            <Line theme={theme} who="you" interim aria-hidden="true">
              <span className="who">You</span>
              <span className="said">
                {interimTranscript}
                <span className="type-caret" />
              </span>
            </Line>
          )}

          {assistantState === "thinking" && (
            <Line theme={theme} who="ai" aria-hidden="true">
              <span className="who">{name}</span>
              <span className="said">
                <ThinkingDots>
                  <i />
                  <i />
                  <i />
                </ThinkingDots>
              </span>
            </Line>
          )}
        </BubbleScroll>

        {assistantState === "idle" && (followUps.length > 0 || greeting) && (
          <ChipRow>
            {(followUps.length > 0
              ? followUps.map((f) => f.question)
              : OPENERS
            ).map((question, i) => (
              <Chip
                key={`${question}-${i}`}
                type="button"
                theme={theme}
                onClick={() => submitText(question)}
              >
                {question}
              </Chip>
            ))}
          </ChipRow>
        )}

        {showTextInput && (
          <TypeForm
            onSubmit={(e) => {
              e.preventDefault();
              if (textInput.trim()) submitText(textInput);
            }}
          >
            <TypeInput
              ref={textInputRef}
              theme={theme}
              value={textInput}
              onChange={(e) => setTextInput(e.target.value)}
              placeholder={`Ask ${name} about Laxman...`}
              aria-label={`Type a question for ${name}`}
            />
            <IconButton type="submit" theme={theme} wide aria-label="Send">
              Send
            </IconButton>
          </TypeForm>
        )}

        <BubbleBar>
          <IconButton
            type="button"
            theme={theme}
            wide
            active={assistantState === "listening"}
            onClick={onMicButton}
            aria-label={
              isDisabled
                ? "Enable your microphone"
                : assistantState === "idle"
                ? `Talk to ${name}`
                : "Stop"
            }
          >
            <MicrophoneIcon
              size={14}
              color="currentColor"
              animated={assistantState === "listening"}
            />
            {isDisabled
              ? "Enable mic"
              : assistantState === "idle"
              ? "Talk"
              : "Stop"}
          </IconButton>

          <IconButton
            type="button"
            theme={theme}
            active={showTextInput}
            onClick={() => setShowTextInput((v) => !v)}
            aria-pressed={showTextInput}
            aria-label="Type instead of talking"
          >
            <KeyboardGlyph />
          </IconButton>

          <span className="spacer" />

          {transcriptEntries.length > 0 && (
            <IconButton
              type="button"
              theme={theme}
              wide
              onClick={clearTranscript}
              aria-label="Clear the conversation"
            >
              Clear
            </IconButton>
          )}

          <IconButton
            type="button"
            theme={theme}
            onClick={closeChat}
            aria-label={`Let ${name} go back to wandering`}
          >
            <CloseGlyph />
          </IconButton>

          {/* Opt out. Some visitors will not want a cat on the page, and the
              only other way to get rid of it was to leave. */}
          {onDisable && (
            <IconButton
              type="button"
              theme={theme}
              wide
              onClick={onDisable}
              title={`Hide ${name} on this device`}
              aria-label={`Turn ${name} off and stop showing the pet`}
            >
              Turn off
            </IconButton>
          )}
        </BubbleBar>
      </Bubble>
    </>
  );
};

export default PetBrain;
